insert into public.activities
  (id, title_en, title_bn, domain, routine_slot, age_bands, comm_levels, difficulty, minutes, why_bn, needs_bn, steps, success_bn, if_upset_bn, safety_note_bn, conflicts_with_flags, evidence, status, version)
values
('COM-01', 'Two-choice snack', 'দুটি খাবারের মধ্যে বাছাই', 'communication', 'mealtime', ARRAY['under_3','3_5','6_9']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'শিশু চাওয়ার জন্য তাকানো, আঙুল দেখানো বা শব্দ ব্যবহার করতে শেখে।', ARRAY['শিশুর পছন্দের দুটি খাবার','একটি ছোট প্লেট']::text[], '[{"text_bn":"শিশুর সামনে বসুন, দুই হাতে দুটি খাবার ধরুন।","text_en":"Sit in front of your child and hold one snack in each hand.","image":"/library/COM-01/step-1.webp"},{"text_bn":"খাবার দুটির নাম বলুন: \"বিস্কুট না কলা?\"","text_en":"Name both snacks: \"Biscuit or banana?\"","image":"/library/COM-01/step-2.webp"},{"text_bn":"চুপ করে ৫ সেকেন্ড অপেক্ষা করুন।","text_en":"Stay quiet and wait 5 seconds.","image":"/library/COM-01/step-3.webp"},{"text_bn":"শিশু তাকালে, আঙুল দেখালে বা শব্দ বললে সেটির নাম বলে দিন: \"কলা!\"","text_en":"When your child looks, points or says a word, name it: \"Banana!\"","image":"/library/COM-01/step-4.webp"},{"text_bn":"সঙ্গে সঙ্গে বেছে নেওয়া খাবারের ছোট একটি টুকরো দিন।","text_en":"Give a small piece of the chosen snack right away.","image":"/library/COM-01/step-5.webp"}]'::jsonb, 'শিশু তাকিয়ে, আঙুল দেখিয়ে বা শব্দ বলে অন্তত ৩ বার বেছে নেয়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY['food_allergy']::text[], ARRAY['PRT','NCAEP: time delay']::text[], 'reviewed', 1),
('COM-02', 'Ready, set… go!', 'রেডি, সেট… গো!', 'communication', 'play', ARRAY['under_3','3_5','6_9']::text[], ARRAY['preverbal','words_gestures','phrases','aac']::text[], 1, 5, 'শিশু খেলা চালু রাখতে একটি শব্দ বা ইশারা ব্যবহার করতে শেখে।', ARRAY['একটি বল বা খেলনা গাড়ি']::text[], '[{"text_bn":"মেঝেতে শিশুর মুখোমুখি বসুন, মাঝখানে বলটি রাখুন।","text_en":"Sit on the floor facing your child with the ball between you.","image":"/library/COM-02/step-1.webp"},{"text_bn":"আনন্দ করে বলুন: \"রেডি, সেট… গো!\" আর বলটি গড়িয়ে দিন।","text_en":"Say happily: \"Ready, set… go!\" and roll the ball.","image":"/library/COM-02/step-2.webp"},{"text_bn":"আবার বলুন \"রেডি, সেট…\" তারপর থেমে শিশুর দিকে তাকিয়ে অপেক্ষা করুন।","text_en":"Say \"Ready, set…\" again, then stop and wait, looking at your child.","image":"/library/COM-02/step-3.webp"},{"text_bn":"শিশু \"গো\" বললে, ইশারা করলে বা শব্দ করলে সঙ্গে সঙ্গে বল গড়িয়ে দিন।","text_en":"When your child says \"go\", signs or makes a sound, roll the ball right away.","image":"/library/COM-02/step-4.webp"},{"text_bn":"শিশু আনন্দ পাওয়া পর্যন্ত কয়েকবার করুন।","text_en":"Repeat a few times while your child is having fun.","image":"/library/COM-02/step-5.webp"}]'::jsonb, 'শিশু অন্তত ২ বার "গো" বলে বা ইশারা করে খেলা শুরু করায়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['NCAEP: time delay','NCAEP: naturalistic intervention']::text[], 'reviewed', 1),
('COM-03', 'Picture card for "more"', '"আরও" ছবির কার্ড', 'communication', 'mealtime', ARRAY['under_3','3_5','6_9','10_plus']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'কথা না বললেও শিশু ছবি দিয়ে "আরও" চাইতে শেখে।', ARRAY['"আরও" লেখা একটি ছবির কার্ড','শিশুর পছন্দের খাবার']::text[], '[{"text_bn":"খাবারের সময় \"আরও\" কার্ডটি শিশুর পাশে টেবিলে রাখুন।","text_en":"At mealtime, put the \"more\" card on the table next to your child.","image":"/library/COM-03/step-1.webp"},{"text_bn":"খাবারের ছোট একটি টুকরো দিন, শেষ হওয়া পর্যন্ত অপেক্ষা করুন।","text_en":"Give a small bite and wait until it is finished.","image":"/library/COM-03/step-2.webp"},{"text_bn":"শিশু আরও চাইলে কার্ডটি দেখান আর বলুন \"আরও?\"","text_en":"When your child wants more, show the card and say \"More?\"","image":"/library/COM-03/step-3.webp"},{"text_bn":"শিশু কার্ডটি ছুঁলে বা আপনার হাতে দিলে বলুন \"আরও!\" আর আরেকটি টুকরো দিন।","text_en":"When your child touches or hands you the card, say \"More!\" and give another bite.","image":"/library/COM-03/step-4.webp"},{"text_bn":"প্রথম দিকে দরকার হলে শিশুর হাত আলতো করে কার্ডের দিকে নিয়ে যান, পরে সাহায্য কমান।","text_en":"At first, gently guide your child''s hand to the card if needed, then help less.","image":"/library/COM-03/step-5.webp"}]'::jsonb, 'শিশু নিজে থেকে কার্ড ছুঁয়ে বা দিয়ে অন্তত ৩ বার আরও চায়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY['food_allergy']::text[], ARRAY['NCAEP: AAC','NCAEP: functional communication training']::text[], 'reviewed', 1),
('SOC-01', 'Face-to-face bubbles', 'মুখোমুখি বাবল খেলা', 'social', 'play', ARRAY['under_3','3_5','6_9']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'শিশু আপনার মুখের দিকে তাকাতে আর আনন্দ ভাগ করতে শেখে।', ARRAY['একটি বাবল বোতল']::text[], '[{"text_bn":"শিশুর চোখের সমান উচ্চতায় মুখোমুখি বসুন।","text_en":"Sit face to face at your child''s eye level.","image":"/library/SOC-01/step-1.webp"},{"text_bn":"কয়েকটি বাবল উড়িয়ে আনন্দ করে বলুন: বাবল!","text_en":"Blow a few bubbles and say \"bubbles!\" happily.","image":"/library/SOC-01/step-2.webp"},{"text_bn":"থামুন, বোতলটি আপনার মুখের কাছে ধরে ৫ সেকেন্ড অপেক্ষা করুন।","text_en":"Stop, hold the bottle near your face and wait 5 seconds.","image":"/library/SOC-01/step-3.webp"},{"text_bn":"শিশু তাকালে, আঙুল দেখালে বা শব্দ করলে সঙ্গে সঙ্গে আবার বাবল উড়ান।","text_en":"When your child looks, points or makes a sound, blow bubbles again right away.","image":"/library/SOC-01/step-4.webp"},{"text_bn":"শিশু যতক্ষণ আনন্দ পাচ্ছে, ৫–১০ বার করুন।","text_en":"Repeat 5–10 times while your child enjoys it.","image":"/library/SOC-01/step-5.webp"}]'::jsonb, 'শিশু আরও চাওয়ার জন্য অন্তত ৩ বার আপনার মুখের দিকে তাকায়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['JASPER','PACT','NCAEP: time delay','NCAEP: naturalistic intervention']::text[], 'reviewed', 1),
('SOC-02', 'Song with a pause', 'থেমে থেমে গান', 'social', 'any', ARRAY['under_3','3_5']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'শিশু আপনার সাথে পালা করে খেলতে আর যোগ দিতে শেখে।', ARRAY['শিশুর প্রিয় একটি ছড়া বা গান']::text[], '[{"text_bn":"শিশুর মুখোমুখি বসে প্রিয় গানটি হাসিমুখে গাইতে শুরু করুন।","text_en":"Sit facing your child and start singing the favourite song with a smile.","image":"/library/SOC-02/step-1.webp"},{"text_bn":"কয়েকবার পুরো গানটি গেয়ে শোনান, সাথে হাতের ভঙ্গি করুন।","text_en":"Sing the whole song a few times with hand actions.","image":"/library/SOC-02/step-2.webp"},{"text_bn":"এবার একটি চেনা শব্দের ঠিক আগে থেমে শিশুর দিকে তাকিয়ে অপেক্ষা করুন।","text_en":"Now stop just before a familiar word and wait, looking at your child.","image":"/library/SOC-02/step-3.webp"},{"text_bn":"শিশু শব্দ, আওয়াজ বা ভঙ্গি করলে খুশি হয়ে গান আবার চালিয়ে যান।","text_en":"When your child makes a word, sound or action, happily carry on singing.","image":"/library/SOC-02/step-4.webp"}]'::jsonb, 'শিশু থামার জায়গায় অন্তত ২ বার শব্দ, আওয়াজ বা ভঙ্গি দিয়ে যোগ দেয়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['JASPER','PACT']::text[], 'reviewed', 1),
('PLY-01', 'Copy, then add one', 'নকল করুন, তারপর একটি যোগ করুন', 'imitation_play', 'play', ARRAY['under_3','3_5','6_9']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'শিশু আপনাকে দেখে নতুন উপায়ে খেলতে শেখে।', ARRAY['একই রকম দুটি খেলনা (যেমন দুটি গাড়ি বা দুটি ব্লক)']::text[], '[{"text_bn":"শিশুর পাশে বসুন, একই রকম খেলনা নিজের হাতে নিন।","text_en":"Sit beside your child and take a matching toy for yourself.","image":"/library/PLY-01/step-1.webp"},{"text_bn":"শিশু খেলনা দিয়ে যা করছে, ঠিক সেটাই নকল করুন।","text_en":"Copy exactly what your child does with the toy.","image":"/library/PLY-01/step-2.webp"},{"text_bn":"আপনি কী করছেন সহজ শব্দে বলুন: \"গাড়ি চলে!\"","text_en":"Say what you are doing in simple words: \"Car goes!\"","image":"/library/PLY-01/step-3.webp"},{"text_bn":"কিছুক্ষণ পর নতুন একটি কাজ যোগ করুন, যেমন গাড়িকে ব্লকের উপর তুলুন।","text_en":"After a while, add one new action, like driving the car up a block.","image":"/library/PLY-01/step-4.webp"},{"text_bn":"শিশু নকল করলে খুশি হয়ে প্রশংসা করুন, না করলে আবার শিশুকে নকল করুন।","text_en":"If your child copies you, praise happily; if not, go back to copying your child.","image":"/library/PLY-01/step-5.webp"}]'::jsonb, 'শিশু আপনার নতুন কাজটি অন্তত একবার নকল করে।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['Project ImPACT: reciprocal imitation','NCAEP: modelling']::text[], 'reviewed', 1),
('PLY-02', 'Feed the doll', 'পুতুলকে খাওয়ানো', 'imitation_play', 'play', ARRAY['3_5','6_9']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 5, 'শিশু ভান করে খেলা আর অন্যের কথা ভাবা শেখে।', ARRAY['একটি পুতুল বা নরম খেলনা','একটি খেলনা চামচ ও বাটি']::text[], '[{"text_bn":"পুতুল, চামচ আর বাটি শিশুর সামনে রাখুন।","text_en":"Put the doll, spoon and bowl in front of your child.","image":"/library/PLY-02/step-1.webp"},{"text_bn":"বলুন \"পুতুলের খিদে পেয়েছে!\" আর চামচ দিয়ে পুতুলকে ভান করে খাওয়ান।","text_en":"Say \"Dolly is hungry!\" and pretend to feed the doll with the spoon.","image":"/library/PLY-02/step-2.webp"},{"text_bn":"\"হাম হাম, মজা!\" বলে আনন্দ দেখান।","text_en":"Show the fun: \"Yum yum, tasty!\"","image":"/library/PLY-02/step-3.webp"},{"text_bn":"চামচটি শিশুর দিকে এগিয়ে দিয়ে বলুন: \"তোমার পালা।\"","text_en":"Hold the spoon out to your child and say: \"Your turn.\"","image":"/library/PLY-02/step-4.webp"},{"text_bn":"শিশু খাওয়ালে বা চেষ্টা করলে প্রশংসা করুন: \"পুতুল খুশি!\"","text_en":"When your child feeds the doll or tries, praise them: \"Dolly is happy!\"","image":"/library/PLY-02/step-5.webp"}]'::jsonb, 'শিশু অন্তত একবার নিজে পুতুলকে ভান করে খাওয়ায়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['JASPER: symbolic play','NCAEP: modelling']::text[], 'reviewed', 1),
('SEN-01', 'Calm-down corner', 'শান্ত হওয়ার কোণ', 'sensory', 'any', ARRAY['under_3','3_5','6_9','10_plus']::text[], ARRAY['preverbal','words_gestures','phrases','conversational','aac']::text[], 1, 10, 'অস্থির লাগলে শিশু শান্ত হওয়ার একটি নিরাপদ জায়গা পায়।', ARRAY['ঘরের একটি নিরিবিলি কোণ','একটি নরম বালিশ বা কম্বল','শিশুর প্রিয় নরম খেলনা']::text[], '[{"text_bn":"ঘরের একটি নিরিবিলি কোণে নরম বালিশ আর প্রিয় খেলনা রাখুন।","text_en":"Put a soft cushion and a favourite toy in a quiet corner.","image":"/library/SEN-01/step-1.webp"},{"text_bn":"শিশু শান্ত থাকা অবস্থায় একসাথে কোণে গিয়ে কিছুক্ষণ বসুন।","text_en":"While your child is calm, go and sit in the corner together for a little while.","image":"/library/SEN-01/step-2.webp"},{"text_bn":"শিশু অস্থির হতে শুরু করলে শান্ত গলায় বলুন \"চলো, শান্ত কোণে যাই।\"","text_en":"When your child starts to get upset, say calmly: \"Let''s go to the calm corner.\"","image":"/library/SEN-01/step-3.webp"},{"text_bn":"কোণে শিশুর পাশে চুপচাপ থাকুন, কম কথা বলুন।","text_en":"Stay quietly beside your child in the corner and talk very little.","image":"/library/SEN-01/step-4.webp"},{"text_bn":"শিশু শান্ত হলে নরম গলায় প্রশংসা করুন।","text_en":"When your child is calm, praise them softly.","image":"/library/SEN-01/step-5.webp"}]'::jsonb, 'শিশু অস্থির হলে আপনার সাথে কোণে যায় এবং আগের চেয়ে তাড়াতাড়ি শান্ত হয়।', 'থামুন, শান্তভাবে একটু বিরতি দিন, পরে বা আগামীকাল আবার চেষ্টা করুন।', 'শিশুকে কখনো জোর করবেন না বা চেপে ধরবেন না। শিশু অস্থির হলে থামুন। শাস্তি হিসেবে কখনো খাবার বা আদর বন্ধ করবেন না। নতুন কোনো চিন্তার আচরণ দেখলে ক্লিনিকে যোগাযোগ করুন।', ARRAY[]::text[], ARRAY['NCAEP: antecedent-based intervention']::text[], 'reviewed', 1),
