-- The live activities table was never seeded (0 rows), so the AI intake route had no
-- valid ids to choose from and every roadmap ended up with zero plan_items — which is
-- why "Today's practice" showed empty for both the therapist and the parent. This
-- loads the canonical 16-activity library already authored in web/data/activities.json
-- (generated via a one-off Node script, not hand-written).
on conflict (id) do update set
  title_en = excluded.title_en, title_bn = excluded.title_bn, domain = excluded.domain, routine_slot = excluded.routine_slot,
  age_bands = excluded.age_bands, comm_levels = excluded.comm_levels, difficulty = excluded.difficulty, minutes = excluded.minutes,
  why_bn = excluded.why_bn, needs_bn = excluded.needs_bn, steps = excluded.steps, success_bn = excluded.success_bn,
  if_upset_bn = excluded.if_upset_bn, safety_note_bn = excluded.safety_note_bn, conflicts_with_flags = excluded.conflicts_with_flags,
  evidence = excluded.evidence, status = excluded.status, version = excluded.version;
